  // receipt call identity (byte-identical to the previous local hasher).
  return digestStableJson({
    provider: input.providerId ?? input.adapterId ?? 'unknown',
    model: input.modelId ?? null,
    sessionKey: input.sessionKey ?? null,
    runId: input.runId ?? null,
    traceId: input.traceId ?? null,
    attempt: input.attemptIndex ?? 0,
    modelCall: input.modelCallIndex ?? 0,
  });
}

export function recordShadowCensusFailure(
  phase: ShadowCensusFailureDiagnostic['phase'],
  code: ShadowCensusFailureDiagnostic['code'],
): void {
  shadowFailureCount += 1;
  const key = `${phase}:${code}`;
  const existing = shadowFailures.get(key);
  shadowFailures.set(key, { phase, code, count: (existing?.count ?? 0) + 1 });
}

export function getShadowCensusDiagnostics(): {
  failedWrites: number;
  acceptanceReady: boolean;
  failures: ShadowCensusFailureDiagnostic[];
} {
  return {
    failedWrites: shadowFailureCount,
    acceptanceReady: shadowFailureCount === 0,
    failures: [...shadowFailures.values()],
  };
}

export function resetShadowCensusDiagnosticsForTest(): void {
  shadowFailureCount = 0;
  shadowFailures.clear();
}

export function getShadowReceiptOptions(options: unknown): ShadowReceiptOptions | undefined {
  if (!options || typeof options !== 'object') return undefined;
  const candidate = (options as Record<PropertyKey, unknown>)[RC02_SHADOW_OPTIONS];
  return candidate && typeof candidate === 'object' ? (candidate as ShadowReceiptOptions) : undefined;
}

/** Start a source-runtime model call census before provider projection. */
export function beginShadowModelCall(
  logicalContext: unknown,
  input: ShadowReceiptCallContext,
  options: unknown,
): ShadowCallOptionsResult {
  const attached = getShadowReceiptOptions(options) ?? {};
  const rawOptions = options && typeof options === 'object' ? (options as Record<string, unknown>) : {};
  const call = {
    ...input,
    sessionKey:
      input.sessionKey ??
      attached.sessionKey ??
      (typeof rawOptions.sessionId === 'string' ? rawOptions.sessionId : undefined),
    runId:
      input.runId ??
      attached.runId ??
      (typeof rawOptions.runId === 'string' ? rawOptions.runId : undefined),
    traceId:
      input.traceId ??
      attached.traceId ??
      (typeof rawOptions.traceId === 'string' ? rawOptions.traceId : undefined),
    attemptIndex:
      input.attemptIndex ??
      attached.attemptIndex ??
      (typeof rawOptions.attemptIndex === 'number' ? rawOptions.attemptIndex : undefined),
    modelCallIndex:
      input.modelCallIndex ??
      attached.modelCallIndex ??
      (typeof rawOptions.modelCallIndex === 'number' ? rawOptions.modelCallIndex : undefined),
    wireAttemptIndex:
      input.wireAttemptIndex ??
      attached.wireAttemptIndex ??
      (typeof rawOptions.wireAttemptIndex === 'number' ? rawOptions.wireAttemptIndex : undefined),
  };
  const active = isEnabled(attached);
  if (!active) {
    return {
      active: false,
      options: { ...attached, ...call, enabled: false },
      receipt: {
        active: false,
        receipt: null,
        failed: false,
        correlationDigest: null,
        logicalDigest: null,
      },
    };
  }
  if (attached.correlationDigest && attached.logicalDigest) {
    return {
      active,
      options: { ...attached, ...call, enabled: active },
      receipt: {
        active: true,
        receipt: null,
        failed: false,
        correlationDigest: attached.correlationDigest,
        logicalDigest: attached.logicalDigest,
      },
    };
  }
  const receipt = emitShadowContextReceipt(logicalContext, call, { ...attached, enabled: true });
  if (!receipt.active) {
    throw new Error('active shadow model call did not produce an active context receipt result');
  }
  return {
    active: true,
    options: {
      ...attached,
      ...call,
      enabled: true,
      correlationDigest: receipt.correlationDigest,
      logicalDigest: receipt.logicalDigest,
    },
    receipt,
  };
}

export function attachShadowReceiptOptions<T extends object>(options: T | undefined, shadow: ShadowReceiptOptions): T & { [RC02_SHADOW_OPTIONS]: ShadowReceiptOptions } {
  return { ...(options ?? {}), [RC02_SHADOW_OPTIONS]: shadow } as T & { [RC02_SHADOW_OPTIONS]: ShadowReceiptOptions };
}

/** Emit the logical receipt before provider projection. No raw context is stored. */
export function emitShadowContextReceipt(
  logicalContext: unknown,
  input: ShadowReceiptCallContext,
  options: ShadowReceiptOptions = {},
): ShadowContextEmitResult {
  if (!isEnabled(options)) {
    return {
      active: false,
      receipt: null,
      failed: false,
      correlationDigest: null,
      logicalDigest: null,
    };
  }
  const logicalDigest = digestStable(logicalContext);
  const correlation = options.correlationDigest ?? correlationDigest(input);

  const receiptIdentity = identity(input, runtimeMode(options));
  let receipt: PutReceiptResult | null;
  try {
    receipt = shadowStore(options).put({
      idempotencyKey: `ctx:v0:${correlation}`,
      kind: 'shadow_context',
      version: SHADOW_CONTEXT_RECEIPT_VERSION,
      identity: receiptIdentity,
      callIndex: callIndex(input),
      content: { logicalDigest, correlationDigest: correlation },
    });
  } catch {
    recordShadowCensusFailure('context-write', 'receipt-store-write-failed');
    return { active: true, receipt: null, failed: true, correlationDigest: correlation, logicalDigest };
  }
  const failed = !receipt.ok;
  if (failed) recordShadowCensusFailure('context-write', 'receipt-content-conflict');
  return { active: true, receipt, failed, correlationDigest: correlation, logicalDigest };
}

/** Emit the final wire receipt at the guarded request-body boundary. */
export function emitShadowWireReceipt(
  body: string | Uint8Array | Record<string, unknown>,
  input: ShadowReceiptCallContext,
  options: ShadowReceiptOptions = {},
): ShadowWireEmitResult {
  if (!isEnabled(options)) return { receipt: null, failed: false };
  const correlation = options.correlationDigest ?? correlationDigest(input);
  const wireDigest = wireBodyDigest(body);
  let ownerCensus: WireOwnerCensus;
  try {
    // Owner coverage requires a named transport adapter. A provider id is not
    // sufficient evidence because it does not identify the serializer/finalizer.
    ownerCensus = buildWireOwnerCensus(body, input.adapterId);
  } catch {
    recordShadowCensusFailure('wire-owner', 'final-wire-body-invalid');
    return { receipt: null, failed: true };
  }
  if (ownerCensus.unknownCount !== 0 || ownerCensus.duplicateCount !== 0) {
    recordShadowCensusFailure('wire-owner', 'wire-owner-incomplete');
    return { receipt: null, failed: true };
  }
  const receiptIdentity = identity(input, runtimeMode(options));
  let receipt: PutReceiptResult | null;
  try {
    receipt = shadowStore(options).put({
      idempotencyKey: `wire:v0:${correlation}:${input.wireAttemptIndex ?? 0}`,
      kind: 'shadow_wire',
      version: SHADOW_WIRE_RECEIPT_VERSION,
      identity: receiptIdentity,
      callIndex: callIndex(input),
      content: {
        logicalDigest: options.logicalDigest,
        wireDigest,
        correlationDigest: correlation,
        selected: [
          ownerCensus.proofRef,
          ...(options.requestEnvelopeRef ? [options.requestEnvelopeRef] : []),
        ],
      },
    });
  } catch {
    recordShadowCensusFailure('wire-write', 'receipt-store-write-failed');
    return { receipt: null, failed: true };
  }
  const failed = !receipt.ok;
  if (failed) recordShadowCensusFailure('wire-write', 'receipt-content-conflict');
  return { receipt, failed };
}

/** Compatibility helper for narrow unit tests; production uses the two phases. */
export function emitShadowCensus(
  body: Record<string, unknown>,
  input: ShadowReceiptCallContext,
  options: ShadowReceiptOptions = {},
): ShadowCensusEmitResult {
  const context = emitShadowContextReceipt(body, input, options);
  if (!context.active) {
    return { contextReceipt: null, wireReceipt: null, failed: false };
  }
  const wire = emitShadowWireReceipt(body, input, {
    ...options,
    correlationDigest: context.correlationDigest,
    logicalDigest: context.logicalDigest,
  });
  return { contextReceipt: context.receipt, wireReceipt: wire.receipt, failed: context.failed || wire.failed };
}

/** RC-03 WireReceipt/v1 at the guarded boundary. The receipt is bound to the
 *  sealed plan's identity and the final serialized body digest; registered
 *  non-semantic transport transform ids ride on the identity. Observational
 *  only: write failures record census diagnostics and never change send bytes. */
export function emitRc03WireReceipt(
  body: string | Uint8Array | Record<string, unknown>,
  options: ShadowReceiptOptions,
  input: { providerId: string; adapterId: string; modelId?: string; wireAttemptIndex: number },
): PutReceiptResult | null {
  const plan = options.rc03Plan;
  if (!plan) return null;
  const wireDigest = wireBodyDigest(body);
  const correlation = options.correlationDigest ?? correlationDigest({
    providerId: input.providerId,
    adapterId: input.adapterId,
    modelId: input.modelId,
    sessionKey: options.sessionKey,
    runId: options.runId,
    traceId: options.traceId,
    attemptIndex: options.attemptIndex,
    modelCallIndex: options.modelCallIndex,
    wireAttemptIndex: input.wireAttemptIndex,
  });
  const identity: ReceiptIdentity = {
    sessionKey: options.sessionKey,
    runId: options.runId,
    traceId: options.traceId,
    providerId: input.providerId,
    adapterId: input.adapterId,
    transformIds: plan.postSealTransformIds,
    runtimeMode: runtimeMode(options),
  };
  let receipt: PutReceiptResult | null;
  try {
    receipt = shadowStore(options).put({
      idempotencyKey: `wire:v1:${plan.planId}:${correlation}:${input.wireAttemptIndex}`,
      kind: 'wire',
      version: '1',
      identity,
      callIndex: {
        attemptIndex: options.attemptIndex ?? plan.callIndex.attemptIndex,
        modelCallIndex: options.modelCallIndex ?? plan.callIndex.modelCallIndex,
        wireAttemptIndex: input.wireAttemptIndex,
      },
      content: {
        logicalDigest: options.logicalDigest,
        wireDigest,
        correlationDigest: correlation,
        ...(options.requestEnvelopeRef ? { selected: [options.requestEnvelopeRef] } : {}),
      },
    });
  } catch {
    recordShadowCensusFailure('wire-write', 'receipt-store-write-failed');
    return null;
  }
  if (!receipt.ok) {
    recordShadowCensusFailure('wire-write', 'receipt-content-conflict');
  }
  return receipt;
}

export type ProviderEnvelopeRejectionReason =
  | 'request-envelope-incomplete'
  | 'unregistered-transform'
  | 'final-wire-body-unavailable'
  | 'final-wire-body-invalid'
  | 'unknown-envelope';

ex** A payload-free typed failure raised by the opt-in provider boundary. */
export class ProviderEnvelopeRejectedError extends Error {
  readonly code = 'provider_envelope_rejected';
  readonly reason: ProviderEnvelopeRejectionReason;
  readonly envelopeRef?: string;

  constructor(reason: ProviderEnvelopeRejectionReason, envelopeRef?: string) {
    super(`Provider request envelope rejected: ${reason}`);
    this.name = 'ProviderEnvelopeRejectedError';
    this.reason = reason;
    if (envelopeRef) this.envelopeRef = envelopeRef;
  }
}

export type ProviderEnvelopeRejectionInput = {
  ok: boolean;
  reason?: ProviderEnvelopeRejectionReason;
  envelopeRef?: string;
  knownEnvelope: boolean;
};

export function resolveProviderEnvelopeRejectionReason(
  envelope: ProviderEnvelopeRejectionInput,
): ProviderEnvelopeRejectionReason | undefined {
  if (!envelope.knownEnvelope) return 'unknown-envelope';
  if (!envelope.ok) return envelope.reason ?? 'request-envelope-incomplete';
  return undefined;
}

export function shouldRejectProviderEnvelope(
  envelope: ProviderEnvelopeRejectionInput,
  options: ShadowReceiptOptions = {},
): boolean {
  return isProviderEnvelopeRejectionEnabled(options) && resolveProviderEnvelopeRejectionReason(envelope) !== undefined;
}
"},{"path":"harness/specs/tasks/harness-gap-envelope-reject.md","content":"# S01 — Provider request-envelope rejection boundary

## Objective

Upgrade the existing RC-02 Stage 1 request-envelope shadow observation into an independent, opt-in rejecting boundary. When explicitly enabled, an illegal or unknown request envelope must be rejected before `fetchWithSsrFGuard`; no provider bytes may be sent.

## Preconditions

- Reuse the existing Stage 1 envelope builder and RC-02 receipt boundary.
- Reuse the existing digest-only wire receipt. Do not add a store, registry, router, or parallel receipt type.
- The existing shadow-census default and feature-flag behavior remain unchanged.
- SSRF, timeout, proxy, local-service, and outbound-budget behavior remain owned by the existing provider transport.

## Required behavior

1. The rejection switch is independent and opt-in. Missing or false means shadow-only observation and unchanged request bytes.
2. With the switch explicitly enabled, reject an incomplete, invalid, unregistered-transform, or unknown envelope with `ProviderEnvelopeRejectedError`.
3. Evaluation occurs after the digest-only wire receipt attempt and before the guarded fetch call.
4. A rejected request makes zero calls to `fetchWithSsrFGuard` and sends zero provider bytes.
5. The error exposes a typed code and a payload-free reason. It must not expose prompts, messages, media, tools, or request bodies.
6. Flag-off behavior remains observational: record the existing census diagnostic and continue with byte-identical provider request bytes.

## Verification

- Enabled invalid-envelope test observes the typed error and zero guarded-fetch calls.
- Disabled and default tests observe one guarded-fetch call and identical request bytes.
- The wire receipt is attempted before rejection and contains only digests/refs.
- Existing SSRF, timeout, proxy, and outbound-budget tests remain unchanged.
- Runtime typecheck, scoped lint, harness validation/dry-run, comms replay/compare, credential scan, and SHA256SUMS readback pass.
"},{"path":"harness/specs/rules/provider-envelope-reject-boundary.md","content":"# Provider envelope reject boundary

## Rule

The provider request-envelope guard is shadow-only by default. An operator must explicitly enable `envelopeReject` on the attached shadow options (or enable `OPENCLAW_RC02_ENVELOPE_REJECT`) to make invalid or unknown envelopes rejecting.

## Ordering

1. Capture the final provider body and build/evaluate the existing Stage 1 request envelope.
2. Attempt the existing digest-only RC-02 wire receipt.
3. If rejection is enabled and the envelope is invalid or unknown, throw `ProviderEnvelopeRejectedError`.
4. Otherwise enter the unchanged provider transport path, including outbound admission, SSRF policy, timeout, proxy, and local-service handling.

The rejection check must occur before `fetchWithSsrFGuard`. It must not introduce another network call or an alternate provider route.

## Observable contract

- Default/off: exactly the prior shadow observation and provider bytes.
- Enabled/rejected: zero calls to `fetchWithSsrFGuard` and zero provider bytes.
- The typed error has code `provider_envelope_rejected` and a bounded payload-free reason.
- The digest-only receipt remains digest/ref-only and is attempted before rejection.

## Non-goals

This boundary does not own SSRF, timeout, proxy, local-service, outbound-budget, approval, product-lock, or default-value policy.
"},{"path":"docs/dev/harness-gap-closure/s01-envelope-reject.md","content":"# S01 envelope reject closure

## Change

The existing provider Stage 1 request-envelope observation now has an independent opt-in rejection mode. The default remains observation-only. No user-visible provider API, product default, lock, or approval behavior changes.

When enabled, the guarded provider transport writes the existing digest-only wire receipt first and then throws `ProviderEnvelopeRejectedError` for an invalid or unknown envelope. The throw happens before `fetchWithSsrFGuard`, so the rejected request performs zero guarded fetches and sends zero provider bytes.

When disabled, the existing diagnostic is recorded and the provider request proceeds with unchanged bytes.

## Boundaries

The change reuses the RC-02 shadow boundary and receipt store. It does not introduce another store, registry, router, or receipt schema. Network SSRF, timeout, proxy, local-service, and outbound-budget rules are unchanged.

## Operator switch

The in-process opt-in is `ShadowReceiptOptions.envelopeReject: true`. The environment fallback is `OPENCLAW_RC02_ENVELOPE_REJECT=1|true|yes|on`. Missing, false, and unrecognized values do not enable rejection.

## Error safety

`ProviderEnvelopeRejectedError` exposes only a stable code, a bounded reason, and an optional canonical envelope ref. Raw prompts, messages, tools, media, and request bodies are never included.
"}]}
